  "placeholder": "'use client';\n\nimport React, { useEffect, useState } from 'react';\nimport { Button, Flex, Image, theme } from '@ceebee/ui/client';\n\nconst GeneratingProgress: React.FC = () => {\n  const { token } = theme.useToken();\n  const [percent, setPercent] = useState(0);\n  const [status, setStatus] = useState<'idle' | 'generating' | 'complete'>('idle');\n  const imageStyles = {\n    root: { borderRadius: token.borderRadiusLG },\n    image: { borderRadius: token.borderRadiusLG },\n    cover: { borderRadius: token.borderRadiusLG },\n  };\n\n  useEffect(() => {\n    if (status === 'generating' && percent < 100) {\n      const timer = setTimeout(() => {\n        setPercent((prev) => Math.min(prev + Math.random() * 8 + 2, 100));\n      }, 200);\n      return () => clearTimeout(timer);\n    } else if (status === 'generating' && percent >= 100) {\n      const timer = setTimeout(() => {\n        setStatus('complete');\n      }, 200);\n      return () => clearTimeout(timer);\n    }\n  }, [status, percent]);\n\n  const handleStart = () => {\n    setPercent(0);\n    setStatus('generating');\n  };\n\n  const imageNode =\n    status === 'complete' ? (\n      <Image\n        width={200}\n        height={200}\n        styles={imageStyles}\n        src=\"https://zos.alipayobjects.com/rmsportal/jkjgkEfvpUPVyRjUImniVslZfWPnJuuZ.png\"\n      />\n    ) : (\n      <Image\n        width={200}\n        height={200}\n        styles={imageStyles}\n        placeholder={{\n          progress: {\n            percent: Math.round(percent),\n            render: (progress, p) => (\n              <>\n                {progress}\n                <div style={{ marginTop: 8 }}>Generating {p}%</div>\n              </>\n            ),\n          },\n        }}\n      />\n    );\n\n  return (\n    <Flex vertical gap={8}>\n      <Button type=\"primary\" onClick={handleStart} disabled={status === 'generating'}>\n        Generate\n      </Button>\n      {imageNode}\n    </Flex>\n  );\n};\n\nconst App: React.FC = () => {\n  const { token } = theme.useToken();\n  const [random, setRandom] = useState<number>(() => Date.now());\n  const imageStyles = {\n    root: { borderRadius: token.borderRadiusLG },\n    image: { borderRadius: token.borderRadiusLG },\n    cover: { borderRadius: token.borderRadiusLG },\n  };\n\n  return (\n    <>\n      <Flex gap={16} wrap>\n        <Image width={200} height={200} styles={imageStyles} placeholder={{ progress: true }} />\n        <Image\n          width={200}\n          height={200}\n          styles={imageStyles}\n          placeholder={{ progress: { render: () => 'loading...' } }}\n        />\n        <Image\n          width={200}\n          height={200}\n          styles={imageStyles}\n          placeholder={{ progress: { percent: 50 } }}\n        />\n        <Image\n          width={200}\n          height={200}\n          styles={imageStyles}\n          placeholder={{\n            progress: {\n              percent: 75,\n              render: (progress, p) => (\n                <>\n                  {progress}\n                  <div style={{ marginTop: 8 }}>Generating {p}%</div>\n                </>\n              ),\n            },\n          }}\n        />\n      </Flex>\n      <Flex gap={16} wrap style={{ marginTop: 16 }}>\n        <Flex vertical gap={8}>\n          <Button\n            type=\"primary\"\n            onClick={() => {\n              setRandom(Date.now());\n            }}\n          >\n            Reload Image\n          </Button>\n          <Image\n            width={200}\n            height={200}\n            alt=\"basic image\"\n            styles={imageStyles}\n            src={`https://zos.alipayobjects.com/rmsportal/jkjgkEfvpUPVyRjUImniVslZfWPnJuuZ.png?${random}`}\n            placeholder={\n              <div\n                style={{\n                  width: '100%',\n                  height: '100%',\n                  background: 'rgba(255, 255, 255, 0.3)',\n                  backdropFilter: 'blur(10px)',\n                  borderRadius: token.borderRadiusLG,\n                }}\n              />\n            }\n          />\n        </Flex>\n        <GeneratingProgress />\n      </Flex>\n    </>\n  );\n};\n\nexport default App;\n",
